for _k, _items in _PROSE_C_RAW.items():
    _norm = []
    for _s in _items:
        _m = re.match(r"^As the ([^,]+), (.*)$", _s, re.S)
        if not _m:
            raise ValueError(f"sl_book_prose: ch {_k} entry does not match 'As the X, ...' shape")
        _v = _VOICE_MAP.get(_m.group(1))
        if not _v:
            raise ValueError(f"sl_book_prose: unknown voice '{_m.group(1)}'")
        _norm.append((_v, _m.group(2)))
    _PROSE_C[_k] = _norm
del _k, _items, _norm, _s, _m, _v

PROSE = {}
